/**
 * Derived PBR maps for the planet albedos.
 *
 * Normal maps are generated by scripts/deriveNormalMaps.mjs and committed
 * alongside the albedos. The sun is deliberately absent: it renders emissive,
 * where a normal map has no meaning.
 */

// Kept in sync with the script's output. An explicit set rather than probing
// for the file, so a missing map is a no-op instead of a 404 mid-render.
const HAS_NORMAL = new Set([
  'earth', 'jupiter', 'mars', 'mercury', 'neptune', 'saturn', 'uranus', 'venus',
]);

/**
 * Per-planet roughness. Every material in the scene used a flat 0.7, which is
 * why the bodies read as the same substance painted different colours. These
 * are scalars rather than maps: one value per body gets most of the benefit for
 * no extra texture bandwidth.
 */
const ROUGHNESS = {
  mercury: 0.94,  // airless, dusty regolith — almost no specular
  mars:    0.88,
  venus:   0.72,  // thick cloud deck, softly glossy
  earth:   0.65,  // oceans pull the average down
  jupiter: 0.58,  // gas, smooth highlight across the bands
  saturn:  0.58,
  uranus:  0.50,
  neptune: 0.50,
  sun:     1.00,
};

function bodyName(url) {
  const m = /\/textures\/([a-z]+)\.webp(?:$|\?)/.exec(url || '');
  return m ? m[1] : null;
}

/** Path to the derived normal map, or null if this body has none. */
export function normalMapFor(albedoUrl) {
  const n = bodyName(albedoUrl);
  return n && HAS_NORMAL.has(n) ? `/textures/${n}_n.webp` : null;
}

/** Per-body roughness, falling back to the previous flat value. */
export function roughnessFor(albedoUrl, fallback = 0.7) {
  const n = bodyName(albedoUrl);
  return (n && ROUGHNESS[n] !== undefined) ? ROUGHNESS[n] : fallback;
}
